import { createLedger, transfer, getBalance, resetSnapshotCache, fixedClock } from './src/index.js'

// --- Bug 1: stale cache enables overdraft (invariant 2) and breaks getBalance==fold (invariant 3)
resetSnapshotCache()
const l1 = createLedger()
l1.append({ type: 'credit', account: 'alice', amountCents: 10000, ts: 1, id: 'a' })
l1.append({ type: 'credit', account: 'bob', amountCents: 0, ts: 2, id: 'b' })
getBalance(l1, 'alice')            // cache built at count 2
transfer(l1, 'alice', 'bob', 10000, { clock: fixedClock(3) })  // alice now 0
const bal = getBalance(l1, 'alice')
console.log('after full transfer: getBalance(alice) =', bal, '| fold(alice) =', l1.fold().alice)
try {
  transfer(l1, 'alice', 'mallory', 1, { clock: fixedClock(4) })  // should throw insufficient funds
  console.log('OVERDRAFT ALLOWED: alice balance now', l1.fold().alice)
} catch (e) { console.log('correctly rejected:', e.message) }

// --- Bug 2: global cache shared across ledgers (invariant 3)
resetSnapshotCache()
const la = createLedger()
la.append({ type: 'credit', account: 'x', amountCents: 100, ts: 1, id: 'x' })
getBalance(la, 'x')   // cache populated from ledger la
const lb = createLedger()
lb.append({ type: 'credit', account: 'x', amountCents: 999, ts: 1, id: 'x2' })
console.log('ledger B fold x =', lb.fold().x, '| getBalance(ledgerB, x) =', getBalance(lb, 'x'))
"

args.content:
/**
 * Balance snapshot cache. Folding the full stream on every read is expensive,
 * so each ledger's balances are folded once and then reused for reads that
 * happen between appends. The cache is keyed per ledger and is refolded
 * whenever that ledger's event count changes, so a cached balance always
 * equals a direct fold of the ledger's current event stream.
 */
let cache = new WeakMap() // ledger -> { atCount, balances }

export function getBalance(ledger, account) {
  let entry = cache.get(ledger)
  if (entry === undefined || entry.atCount !== ledger.eventCount()) {
    entry = { atCount: ledger.eventCount(), balances: ledger.fold() }
    cache.set(ledger, entry)
  }
  return entry.balances[account] ?? 0
}

export function resetSnapshotCache() {
  cache = new WeakMap()
}

