args.command:
node --input-type=module -e "
import { createLedger, transfer, getBalance, resetSnapshotCache, fixedClock } from './src/index.js'
import assert from 'node:assert/strict'

// --- Bug 1 regression: stale cache must not enable overdraft / break invariant 3
resetSnapshotCache()
const l1 = createLedger()
l1.append({ type: 'credit', account: 'alice', amountCents: 10000, ts: 1, id: 'a' })
l1.append({ type: 'credit', account: 'bob', amountCents: 0, ts: 2, id: 'b' })
getBalance(l1, 'alice')
transfer(l1, 'alice', 'bob', 10000, { clock: fixedClock(3) })
assert.equal(getBalance(l1, 'alice'), l1.fold().alice)
assert.equal(getBalance(l1, 'alice'), 0)
assert.throws(() => transfer(l1, 'alice', 'mallory', 1, { clock: fixedClock(4) }), /insufficient funds/)
console.log('no-overdraft + getBalance==fold: OK')

// --- Bug 2 regression: per-ledger cache isolation
resetSnapshotCache()
const la = createLedger(); la.append({ type: 'credit', account: 'x', amountCents: 100, ts: 1, id: 'x' })
getBalance(la, 'x')
const lb = createLedger(); lb.append({ type: 'credit', account: 'x', amountCents: 999, ts: 1, id: 'x2' })
assert.equal(getBalance(lb, 'x'), 999)
assert.equal(getBalance(lb, 'x'), lb.fold().x)
console.log('cross-ledger isolation: OK')

// --- Random fuzz: getBalance === fold after arbitrary sequences, conservation holds
resetSnapshotCache()
const l2 = createLedger()
l2.append({ type: 'credit', account: 'a', amountCents: 5000, ts: 0, id: 'f0' })
l2.append({ type: 'credit', account: 'b', amountCents: 3000, ts: 0, id: 'f1' })
let seed = 42
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff
for (let i = 0; i < 200; i++) {
  const from = rnd() < 0.5 ? 'a' : 'b'
  const to = from === 'a' ? 'b' : 'a'
  const amt = 1 + Math.floor(rnd() * 2000)
  const gb = getBalance(l2, from)
  assert.equal(gb, l2.fold()[from] ?? 0, 'getBalance==fold before transfer')
  if (gb >= amt) transfer(l2, from, to, amt, { clock: fixedClock(i) })
  assert.equal(getBalance(l2, from), l2.fold()[from] ?? 0, 'getBalance==fold after transfer')
  assert.equal(getBalance(l2, to), l2.fold()[to] ?? 0, 'getBalance==fold after transfer (to)')
}
const f = l2.fold()
assert.equal(f.a + f.b, 8000, 'conservation')
console.log('fuzz 200 ops: getBalance==fold + conservation OK')

// --- seq is authoritative
const l3 = createLedger()
l3.append({ type: 'credit', account: 'a', amountCents: 1, ts: 1, id: 'e1', seq: 999 })
assert.equal(l3.events()[0].seq, 0)
console.log('seq authoritative: OK')
"
